SELECT x.result, x.body,
  json_insert(json_insert(json_insert(json_patch(json_patch('{}', json_object('result', x.result, 'item', x.item, 'sha', x.sha, 'status', x.status, 'started', x.started, 'finished', x.finished, 'version', x.version, 'before_clock', CASE WHEN coalesce(x.before_clock_name, x.before_clock_status, x.before_clock_log, x.before_clock_seconds) IS NOT NULL THEN json_object('name', x.before_clock_name, 'status', x.before_clock_status, 'log', x.before_clock_log, 'seconds', x.before_clock_seconds) END, 'name', x.name, 'summary', x.summary, 'remote', x.remote, 'branch', x.branch, 'handoff_sha', x.handoff_sha, 'base_tag', x.base_tag, 'release', x.release, 'install', x.install, 'loopctl', x.loopctl, 'failed_step', x.failed_step, 'bump', x.bump, 'verdicts', x.verdicts, 'allow_diffcov', x.allow_diffcov, 'pid_stamp', x.pid_stamp, 'grace_over', CASE WHEN coalesce(x.grace_over_from, x.grace_canary_sha, x.grace_why, x.grace_count, (SELECT 1 FROM ship_grace c WHERE c.result = x.result LIMIT 1)) IS NOT NULL THEN json_object('over_from', x.grace_over_from, 'canary_sha', x.grace_canary_sha, 'why', x.grace_why, 'count', x.grace_count, 'repos', json(nullif(nullif((SELECT json_group_object(g.repo, json(g.v)) FROM (SELECT c.repo, json_group_array(c.value ORDER BY c.ord) AS v FROM ship_grace c WHERE c.result = x.result GROUP BY c.repo) g), '[]'), '{}'))) END, 'bisect', CASE WHEN coalesce(x.bisect_base, x.bisect_culprit, x.bisect_since, x.bisect_subject, x.bisect_fault, x.bisect_candidate, x.bisect_lands, x.bisect_flake, (SELECT 1 FROM ship_lists c WHERE c.result = x.result AND c.kind = 'bisect_test' LIMIT 1), (SELECT 1 FROM ship_bisect c WHERE c.result = x.result AND c.kind = 'run' LIMIT 1), (SELECT 1 FROM ship_bisect c WHERE c.result = x.result AND c.kind = 'confirm' LIMIT 1)) IS NOT NULL THEN json_object('base', x.bisect_base, 'culprit', x.bisect_culprit, 'since', x.bisect_since, 'subject', x.bisect_subject, 'fault', x.bisect_fault, 'candidate', x.bisect_candidate, 'lands', x.bisect_lands, 'flake', CASE x.bisect_flake WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'tests', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = x.result AND c.kind = 'bisect_test'), '[]'), '{}')), 'runs', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('sha', c.sha, 'verdict', c.verdict)) ORDER BY c.ord) FROM ship_bisect c WHERE c.result = x.result AND c.kind = 'run'), '[]'), '{}')), 'confirm', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('sha', c.sha, 'verdict', c.verdict)) ORDER BY c.ord) FROM ship_bisect c WHERE c.result = x.result AND c.kind = 'confirm'), '[]'), '{}'))) END, 'bisect_step', CASE WHEN coalesce(x.bisect_step_sha, x.bisect_step_n, x.bisect_step_lands, x.bisect_step_recheck) IS NOT NULL THEN json_object('sha', x.bisect_step_sha, 'n', x.bisect_step_n, 'lands', x.bisect_step_lands, 'recheck', CASE x.bisect_step_recheck WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'quiet', CASE WHEN coalesce(x.quiet_off, x.quiet_unmeasured, x.quiet_min_idle_pct, x.quiet_max_s, x.quiet_idle_pct_first, x.quiet_idle_pct, x.quiet_waited_s, x.quiet_load1, x.quiet_readings, x.quiet_ok) IS NOT NULL THEN json_object('off', x.quiet_off, 'unmeasured', x.quiet_unmeasured, 'min_idle_pct', x.quiet_min_idle_pct, 'max_s', x.quiet_max_s, 'idle_pct_first', x.quiet_idle_pct_first, 'idle_pct', x.quiet_idle_pct, 'waited_s', x.quiet_waited_s, 'load1', x.quiet_load1, 'readings', x.quiet_readings, 'quiet', CASE x.quiet_ok WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'diffcov_red', CASE WHEN coalesce(x.diffcov_base, x.diffcov_said, (SELECT 1 FROM ship_diffcov_lines c WHERE c.result = x.result LIMIT 1), (SELECT 1 FROM ship_diffcov_faults c WHERE c.result = x.result LIMIT 1)) IS NOT NULL THEN json_object('base', x.diffcov_base, 'said', x.diffcov_said, 'lines', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'commit', c.commit_sha, 'land', c.land, 'subject', c.subject, 'line', c.line)) ORDER BY c.ord) FROM ship_diffcov_lines c WHERE c.result = x.result), '[]'), '{}')), 'faults', json(nullif(nullif((SELECT json_group_object(c.fault, c.said) FROM ship_diffcov_faults c WHERE c.result = x.result), '[]'), '{}'))) END, 'land_wait_s', x.land_wait_s, 'own_s', x.own_s, 'load1', x.load1, 'timeout_s', x.timeout_s, 'pid', x.pid, 'release_pushes', CASE x.release_pushes WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'progress', CASE x.progress WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'preflight', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = x.result AND c.kind = 'preflight'), '[]'), '{}')), 'undo', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = x.result AND c.kind = 'undo'), '[]'), '{}')), 'tail', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM ship_lists c WHERE c.result = x.result AND c.kind = 'tail'), '[]'), '{}')), 'steps', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('name', c.name, 'log', c.log, 'status', c.status, 'why', c.why, 'timings', c.timings, 'profiles', CASE WHEN c.profile_audit IS NOT NULL THEN json_array(json_object('audit', c.profile_audit, 'bin', c.profile_bin, 'fresh', c.profile_fresh, 'reused', c.profile_reused)) END, 'seconds', c.seconds, 'idle_pct', c.idle_pct, 'load1_end', c.load1_end, 'code', c.code)) ORDER BY c.ord) FROM ship_steps c WHERE c.result = x.result AND c.kind = 'step'), '[]'), '{}')), 'retried', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('name', c.name, 'log', c.log, 'status', c.status, 'why', c.why, 'timings', c.timings, 'profiles', CASE WHEN c.profile_audit IS NOT NULL THEN json_array(json_object('audit', c.profile_audit, 'bin', c.profile_bin, 'fresh', c.profile_fresh, 'reused', c.profile_reused)) END, 'seconds', c.seconds, 'idle_pct', c.idle_pct, 'load1_end', c.load1_end, 'code', c.code)) ORDER BY c.ord) FROM ship_steps c WHERE c.result = x.result AND c.kind = 'retry'), '[]'), '{}')), 'consumer_pins', json((SELECT json_patch('{}', json_object('tag', p.tag, 'ruff', p.ruff, 'sweep', p.sweep,
  'committed', CASE WHEN p.sweep IS NOT NULL THEN json((SELECT json_group_array(r.repo ORDER BY r.repo) FROM ship_pin_repos r WHERE r.result = p.result AND r.status = 'committed')) END,
  'not_committed', CASE WHEN p.sweep IS NOT NULL THEN json((SELECT json_group_object(r.repo, r.said) FROM ship_pin_repos r WHERE r.result = p.result AND r.status <> 'committed')) END,
  'pushed', CASE WHEN p.sweep IS NULL THEN json((SELECT json_group_array(r.repo ORDER BY r.repo) FROM ship_pin_repos r WHERE r.result = p.result AND r.status = 'pushed')) END,
  'not_pushed', CASE WHEN p.sweep IS NULL THEN json((SELECT json_group_object(r.repo, r.said) FROM ship_pin_repos r WHERE r.result = p.result AND r.status <> 'pushed')) END))
  FROM ship_pins p WHERE p.result = x.result)), 'repo', x.repo, 'quiet_settings', CASE WHEN x.quiet_max_s IS NOT NULL THEN json_array(x.quiet_min_idle_pct, x.quiet_max_s) END)), coalesce(x.rest, '{}')), '$.item', x.item), '$.failed_step', x.failed_step), '$.pid', x.pid) AS doc
FROM ships x
